(()=>{'use strict';
const $=s=>document.querySelector(s), defaults={name:'Nuvem',coins:24,xp:0,level:1,needs:{fome:82,diversao:78,limpeza:88,energia:91},entries:[],last:Date.now(),night:false};let state;try{state={...defaults,...JSON.parse(localStorage.getItem('casaNuvem')||'{}')};state.needs={...defaults.needs,...state.needs};state.entries=Array.isArray(state.entries)?state.entries:[]}catch{state={...defaults,needs:{...defaults.needs},entries:[]}}let toastTimer;
const save=()=>{state.last=Date.now();localStorage.setItem('casaNuvem',JSON.stringify(state))};
function greet(){const n=state.name;$('#pet-label').innerHTML='';const span=document.createElement('span');span.textContent=' ♡';$('#pet-label').textContent=n;$('#pet-label').append(span);$('#pet').setAttribute('aria-label',`${n}, seu bichinho virtual`);$('#level').textContent=state.level;$('#coins').textContent=state.coins;$('#xp-label').textContent=`${state.xp%100} / 100 XP`;$('#xp-bar').style.width=`${state.xp%100}%`;$('#room').classList.toggle('night',state.night);renderNeeds();renderDiary()}
function renderNeeds(){const labels=[['fome','🍓','Barriguinha'],['diversao','🎈','Diversão'],['limpeza','🫧','Limpeza'],['energia','🌙','Energia']];$('#needs').innerHTML='';labels.slice(0,3).forEach(([key,icon,label])=>{const el=document.createElement('div');el.className='need';el.innerHTML=`<div class="need-top"><span>${icon} ${label}</span><span>${Math.round(state.needs[key])}%</span></div><div class="need-track"><i style="width:${Math.max(0,state.needs[key])}%"></i></div>`;$('#needs').append(el)});const lowest=Object.entries(state.needs).sort((a,b)=>a[1]-b[1])[0][0];let mood='Está feliz por ter você aqui.';if(state.needs[lowest]<35){const moods={fome:'Está com fominha… um lanchinho?',diversao:'Quer brincar um pouquinho!',limpeza:'Um banho gostoso ia bem.',energia:'Está quase na hora da soneca.'};mood=moods[lowest]}$('#mood-line').textContent=mood;$('#pet').classList.toggle('sleepy',state.needs.energia<25)}
function addXP(n){state.xp+=n;while(state.xp>=100){state.xp-=100;state.level++;state.coins+=10;toast(`Subiu para o nível ${state.level}! +10 ✦`)}$('#level').textContent=state.level;$('#coins').textContent=state.coins;$('#xp-label').textContent=`${state.xp} / 100 XP`;$('#xp-bar').style.width=`${state.xp}%`}
function renderDiary(){const diary=$('#diary');diary.innerHTML='';if(!state.entries.length){const empty=document.createElement('div');empty.className='empty-diary';empty.innerHTML='<div class="empty-icon">📖</div><b>Nosso caderninho</b><span>As coisas que você contar ficam guardadas aqui.</span>';diary.append(empty);return}state.entries.slice(-60).forEach(entry=>{const wrap=document.createElement('div');wrap.className=`entry ${entry.who==='user'?'user':'pet-reply'}`;const text=document.createElement('div');text.className='entry-text';text.textContent=entry.text;const time=document.createElement('span');time.className='entry-time';time.textContent=entry.time;wrap.append(text,time);diary.append(wrap)});diary.scrollTop=diary.scrollHeight}
function addEntry(who,text){state.entries.push({who,text,time:new Intl.DateTimeFormat('pt-BR',{hour:'2-digit',minute:'2-digit'}).format(new Date())});if(state.entries.length>60)state.entries=state.entries.slice(-60);renderDiary();save()}
function replyFor(text){const t=text.toLowerCase();if(/triste|difícil|mal |cansad|chatead|sozinh|chor/.test(t))return'Poxa, sinto muito. Tô aqui do seu ladinho, tá? 💜';if(/feliz|legal|bom dia|consegui|ótim|maravilh|adorei/.test(t))return'Que alegria! Adoro quando você divide essas coisas comigo! ✨';if(/amo|amor|saudade|gosto de você/.test(t))return'Own… meu coração ficou quentinho. Também gosto muito de você! 💖';if(/obrigad/.test(t))return'Sempre! É muito bom poder conversar com você ☺';if(/oi|olá|ola|oie|bom dia|boa noite/.test(t))return'Oii! Já guardei seu recadinho no nosso caderninho 💌';return'Já guardei no nosso caderninho! Obrigada por me contar 💌'}
function say(text,source='text'){text=text.trim();if(!text)return;addEntry('user',text);const response=replyFor(text);setTimeout(()=>{addEntry('pet',response);$('#speech-bubble').textContent=response;addXP(8);state.coins+=1;$('#coins').textContent=state.coins;save();toast('Recadinho guardado! +8 XP · +1 ✦')},320);if(source==='voice')$('#voice-note').textContent='Prontinho! Sua fala foi guardada no caderninho.'}
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2200)}
$('#talk-form').addEventListener('submit',e=>{e.preventDefault();const input=$('#talk-input');if(input.value.trim()){say(input.value);input.value='';input.focus()}});
document.querySelectorAll('[data-tab]').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('.tab').forEach(t=>t.classList.toggle('active',t.dataset.tab===btn.dataset.tab));document.querySelectorAll('.panel').forEach(p=>p.classList.remove('active'));$(`#${btn.dataset.tab}-panel`).classList.add('active')}));
document.querySelectorAll('[data-say]').forEach(btn=>btn.addEventListener('click',()=>say(btn.dataset.say)));
function celebrate(emoji){const el=document.createElement('div');el.className='float';el.textContent=emoji;$('#float-layer').append(el);setTimeout(()=>el.remove(),1200);$('#pet').classList.remove('happy');void $('#pet').offsetWidth;$('#pet').classList.add('happy');setTimeout(()=>$('#pet').classList.remove('happy'),650)}
document.querySelectorAll('[data-action]').forEach(btn=>btn.addEventListener('click',()=>{const action=btn.dataset.action;const cfg={feed:{cost:3,key:'fome',gain:30,emoji:'🍓',msg:'Que delícia! Nuvem adorou o lanchinho.'},play:{cost:2,key:'diversao',gain:28,emoji:'🪁',msg:'Oba! Brincar com você é a melhor coisa!'},clean:{cost:0,key:'limpeza',gain:34,emoji:'🫧',msg:'Banho tomado! Nuvem está cheirosinha.'},sleep:{cost:0,key:'energia',gain:36,emoji:'💤',msg:'Boa sonequinha! Nuvem descansou.'}}[action];if(state.coins<cfg.cost){toast('Faltam estrelinhas! Converse com Nuvem para ganhar.');return}state.coins-=cfg.cost;state.needs[cfg.key]=Math.min(100,state.needs[cfg.key]+cfg.gain);if(action==='play')state.needs.energia=Math.max(0,state.needs.energia-8);if(action==='feed')state.needs.limpeza=Math.max(0,state.needs.limpeza-3);if(action==='sleep'){state.needs.energia=Math.min(100,state.needs.energia+25);state.night=!state.night}else if(action==='clean')state.needs.energia=Math.max(0,state.needs.energia-2);$('#coins').textContent=state.coins;$('#speech-bubble').textContent=cfg.msg;renderNeeds();celebrate(cfg.emoji);save();toast(cfg.msg)}));
$('#rename').addEventListener('click',()=>{const name=prompt('Como você quer chamar seu bichinho?',state.name);if(name&&name.trim()){state.name=name.trim().slice(0,18);greet();save();toast(`Oi, ${state.name}! Adorei meu nome novo 💜`)}});
let recognition=null,listening=false;const SpeechRecognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(SpeechRecognition){recognition=new SpeechRecognition();recognition.lang='pt-BR';recognition.interimResults=true;recognition.continuous=false;recognition.onstart=()=>{listening=true;$('#mic').classList.add('listening');$('#voice-note').textContent='Estou ouvindo… pode falar!'};recognition.onresult=e=>{let final='';let interim='';for(let i=e.resultIndex;i<e.results.length;i++){if(e.results[i].isFinal)final+=e.results[i][0].transcript;else interim+=e.results[i][0].transcript}if(interim)$('#voice-note').textContent=`Ouvindo: “${interim}”`;if(final){$('#talk-input').value='';say(final,'voice')}};recognition.onerror=e=>{$('#voice-note').textContent=e.error==='not-allowed'?'Permita o microfone nas configurações do navegador.':'Não consegui ouvir. Tente de novo ou escreva sua mensagem.'};recognition.onend=()=>{listening=false;$('#mic').classList.remove('listening')}}else{$('#mic').addEventListener('click',()=>toast('Voz não disponível neste navegador. Escreva sua mensagem!'))}
$('#mic').addEventListener('click',()=>{if(!recognition)return;if(listening){recognition.stop();return}try{recognition.start()}catch{toast('Aguarde um instante e tente novamente.')}});
// Pequeno cuidado offline: necessidades diminuem lentamente, sem zerar enquanto o jogo está fechado.
const elapsed=Math.max(0,Math.min(12,(Date.now()-(state.last||Date.now()))/3600000));if(elapsed){state.needs.fome=Math.max(15,state.needs.fome-elapsed*3);state.needs.diversao=Math.max(15,state.needs.diversao-elapsed*2);state.needs.limpeza=Math.max(20,state.needs.limpeza-elapsed*1.3);state.needs.energia=Math.max(20,state.needs.energia-elapsed*2)}greet();save();
})();

